get-id": "record_farmer_language_spoken", "widget-type": "display", "widget-label": "Language", "widget-readonly": true, "widget-required": false, "widget-data-path": "6b06a95a-9a6c-5a33-a33d-c1625716c59c.farmer_language_spoken"}]}, {"panel-id": "vp_cropsown_cropsown_farmer_profile_section_02_3", "panel-orientation": "vertical", "widgets": [{"widget": "boolean", "widget-id": "record_farmer_disabled", "widget-type": "input", "widget-label": "Has a disability", "widget-readonly": true, "widget-required": false, "widget-data-path": "6b06a95a-9a6c-5a33-a33d-c1625716c59c.farmer_disabled", "widget-data-format": {"allowUnset": true, "booleanControlType": "radio", "booleanRepresentation": "yes-no"}}, {"widget": "display", "widget-id": "record_farmer_disability_type", "widget-type": "display", "widget-label": "Disability type", "widget-readonly": true, "widget-required": false, "widget-data-path": "6b06a95a-9a6c-5a33-a33d-c1625716c59c.farmer_disability_type"}]}]}]}'::jsonb,
